package com.requiredmaterials;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import lombok.extern.slf4j.Slf4j;

/**
 * Parses item lists out of "materials:" chat messages, as a fallback for Construction activities
 * the wiki has no "{{Recipe}}" for (Mahogany Homes, Birdhouses, STASH units, eternal fires).
 *
 * Items come in two orderings - "Oak logs x5" and "8 x Oak plank" - and long lists get split
 * across chat lines wherever the text hits its length limit, not at punctuation.
 * {@link #accumulate} and {@link #appendContinuation} report whether more is still expected.
 */
@Slf4j
class ChatMaterialsParser
{
	private static final Pattern NAME_THEN_QTY_PATTERN = Pattern.compile("^(.*?)\\s*x\\s*(\\d+)$", Pattern.CASE_INSENSITIVE);
	private static final Pattern QTY_THEN_NAME_PATTERN = Pattern.compile("^(\\d+)\\s*x\\s*(.+)$", Pattern.CASE_INSENSITIVE);
	private static final Pattern TAG_PATTERN = Pattern.compile("<[^>]*>");

	private final Map<String, String> pendingRawText = new LinkedHashMap<>();
	private final Map<String, Map<String, Integer>> completed = new LinkedHashMap<>();

	/**
	 * @return true if a continuation line is still expected for partName.
	 */
	boolean accumulate(String partName, String rawMaterialsText)
	{
		return process(partName, rawMaterialsText);
	}

	/**
	 * @return true if a continuation line is still expected for partName.
	 */
	boolean appendContinuation(String partName, String rawMessage)
	{
		String pending = pendingRawText.get(partName);
		if (pending == null)
		{
			return false;
		}
		return process(partName, join(pending, rawMessage.trim()));
	}

	Map<String, Integer> getMaterials(String partName)
	{
		return completed.get(partName);
	}

	private boolean process(String partName, String rawText)
	{
		if (!isComplete(rawText))
		{
			pendingRawText.put(partName, rawText);
			return true;
		}

		pendingRawText.remove(partName);
		completed.put(partName, parseMaterialList(stripTrailingPeriod(normalize(rawText))));
		return false;
	}

	/**
	 * A trailing period ends the plain-text shape. The tagged shape has no terminator, so
	 * completeness is "did the last opened &lt;col&gt; span get closed" - counting tags overall
	 * doesn't work, since a continuation opens a fresh span rather than closing the dangling one.
	 */
	private boolean isComplete(String rawText)
	{
		String trimmed = rawText.trim();
		if (trimmed.endsWith("."))
		{
			return true;
		}

		// Items are only coloured when you're short of them, so a message can arrive with no
		// tags at all - nothing to be mid-way through, so it's whole.
		int lastOpenTag = trimmed.lastIndexOf("<col=");
		if (lastOpenTag == -1)
		{
			return true;
		}

		return trimmed.indexOf("</col>", lastOpenTag) != -1;
	}

	/**
	 * The line-wrap eats the space it breaks on, gluing words together ("Air" + "rune" ->
	 * "Airrune"). Only restored between two letters, where it actually changes meaning.
	 */
	private String join(String pending, String continuation)
	{
		String pendingContent = TAG_PATTERN.matcher(pending).replaceAll("");
		String continuationContent = TAG_PATTERN.matcher(continuation).replaceAll("");

		char lastChar = pendingContent.isEmpty() ? ' ' : pendingContent.charAt(pendingContent.length() - 1);
		char firstChar = continuationContent.isEmpty() ? ' ' : continuationContent.charAt(0);

		boolean droppedSpace = Character.isLetter(lastChar) && Character.isLetter(firstChar);
		return droppedSpace ? pending + " " + continuation : pending + continuation;
	}

	private String normalize(String rawText)
	{
		return TAG_PATTERN.matcher(rawText).replaceAll("").replace('\u00A0', ' ');
	}

	private String stripTrailingPeriod(String s)
	{
		return s.endsWith(".") ? s.substring(0, s.length() - 1) : s;
	}

	private Map<String, Integer> parseMaterialList(String materialsList)
	{
		Map<String, Integer> materials = new LinkedHashMap<>();
		for (String entry : materialsList.split(","))
		{
			String trimmed = entry.trim();
			if (trimmed.isEmpty())
			{
				continue;
			}

			Matcher nameThenQty = NAME_THEN_QTY_PATTERN.matcher(trimmed);
			Matcher qtyThenName = QTY_THEN_NAME_PATTERN.matcher(trimmed);
			if (nameThenQty.matches())
			{
				materials.put(nameThenQty.group(1).trim(), Integer.parseInt(nameThenQty.group(2)));
			}
			else if (qtyThenName.matches())
			{
				materials.put(qtyThenName.group(2).trim(), Integer.parseInt(qtyThenName.group(1)));
			}
			else
			{
				log.debug("Required materials: couldn't parse chat requirement segment '{}'", entry);
			}
		}
		return materials;
	}
}

package com.requiredmaterials;

import java.util.ArrayList;
import java.util.List;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;

/**
 * Reads level requirements from the skill guide's widget text, as a fallback when a Construction
 * item has no wiki recipe.
 *
 * A row's primary skill level is a bare number in its own widget, with any additional skills in a
 * separate "Requires: Level N Skill" widget. The two are siblings related only by sharing a Y
 * position, hence the row-matching below.
 */
class GuideLevelReader
{
	private static final int TOP_LEVEL_SLOT_SCAN = 40;
	private static final Pattern DIGITS_ONLY = Pattern.compile("^\\d+$");
	private static final Pattern BOAT_TYPE_SUFFIX = Pattern.compile("\\s*\\([^)]*\\)$");

	List<String> findLevelRequirements(Client client, String partName, String primarySkill)
	{
		for (int groupId : new int[] {InterfaceID.SKILL_GUIDE, InterfaceID.SKILL_GUIDE_V2})
		{
			for (int childId = 0; childId <= TOP_LEVEL_SLOT_SCAN; childId++)
			{
				Widget w = client.getWidget(groupId, childId);
				if (w == null)
				{
					continue;
				}

				List<Widget> numberWidgets = new ArrayList<>();
				List<Widget> nameWidgets = new ArrayList<>();
				collectRowWidgets(w, numberWidgets, nameWidgets);

				for (Widget nameWidget : nameWidgets)
				{
					List<String> result = extractRequirements(nameWidget, partName, numberWidgets, primarySkill);
					if (result != null)
					{
						return result;
					}
				}
			}
		}
		return new ArrayList<>();
	}

	private void collectRowWidgets(Widget widget, List<Widget> numberWidgets, List<Widget> nameWidgets)
	{
		if (widget == null)
		{
			return;
		}

		String text = widget.getText();
		if (text != null && !text.isEmpty())
		{
			(DIGITS_ONLY.matcher(text.trim()).matches() ? numberWidgets : nameWidgets).add(widget);
		}

		for (Widget[] childArray : new Widget[][] {widget.getChildren(), widget.getDynamicChildren()})
		{
			if (childArray == null)
			{
				continue;
			}
			for (Widget child : childArray)
			{
				if (child != null && child != widget)
				{
					collectRowWidgets(child, numberWidgets, nameWidgets);
				}
			}
		}
	}

	/**
	 * @return the requirement list if nameWidget is the row for partName, else null.
	 */
	private List<String> extractRequirements(Widget nameWidget, String partName, List<Widget> numberWidgets, String primarySkill)
	{
		String text = nameWidget.getText();
		int brIdx = text.indexOf("<br>");
		String bareName = (brIdx != -1 ? text.substring(0, brIdx) : text).trim();

		if (!bareName.equalsIgnoreCase(partName) && !bareName.equalsIgnoreCase(stripBoatTypeSuffix(partName)))
		{
			return null;
		}

		List<String> result = new ArrayList<>();

		Widget sameRowNumber = findWidgetOnSameRow(nameWidget, numberWidgets);
		if (sameRowNumber != null)
		{
			result.add("Level " + sameRowNumber.getText().trim() + " " + primarySkill);
		}

		int requiresIdx = text.indexOf("Requires:");
		if (requiresIdx != -1)
		{
			String stripped = text.substring(requiresIdx + "Requires:".length()).replaceAll("<[^>]*>", "").trim();
			for (String piece : stripped.split(","))
			{
				String p = piece.trim();
				if (!p.isEmpty())
				{
					result.add(p);
				}
			}
		}

		return result;
	}

	private String stripBoatTypeSuffix(String partName)
	{
		return BOAT_TYPE_SUFFIX.matcher(partName).replaceFirst("").trim();
	}

	private Widget findWidgetOnSameRow(Widget target, List<Widget> candidates)
	{
		int targetY = target.getOriginalY();
		Widget best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (Widget candidate : candidates)
		{
			int distance = Math.abs(candidate.getOriginalY() - targetY);
			if (distance < bestDistance)
			{
				bestDistance = distance;
				best = candidate;
			}
		}
		// A generous tolerance since the number sits a little higher/lower than the label text.
		return bestDistance <= 12 ? best : null;
	}
}

package com.requiredmaterials;

import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;

/**
 * How many of an item the player has to hand, across bank and inventory. The bank container only
 * exists once a bank has been opened this session, so {@link BankSnapshot} stands in until then.
 */
@Singleton
class HeldItems
{
	@Inject
	private Client client;

	@Inject
	private BankSnapshot bankSnapshot;

	boolean bankKnown()
	{
		return client.getItemContainer(InventoryID.BANK) != null || bankSnapshot.isKnown();
	}

	int count(int itemId)
	{
		return inBank(itemId) + inInventory(itemId);
	}

	int inBank(int itemId)
	{
		ItemContainer bank = client.getItemContainer(InventoryID.BANK);
		return bank != null ? bank.count(itemId) : bankSnapshot.count(itemId);
	}

	int inInventory(int itemId)
	{
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		return inventory != null ? inventory.count(itemId) : 0;
	}
}

package com.requiredmaterials;

import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileObject;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.config.ConfigManager;

/**
 * What's been seen built in the player's house, so a furniture prerequisite can be answered
 * without asking them.
 *
 * The client offers no direct reading of house contents - no varbit per hotspot - so this reads
 * the scene while they're inside. Built furniture is spawned a few ticks after the scene loads,
 * and lives across all four kinds of tile object (a tool store is on a wall, not the floor), so
 * the scan is deliberately late and covers all of them.
 *
 * Results are remembered per account, so the answer survives leaving the house and restarting
 * the client.
 */
@Slf4j
@Singleton
class HouseContents
{
	private static final String CONFIG_KEY = "houseObjects";

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private WikiRecipeService wikiRecipeService;

	private Set<Integer> seen;
	/** The most recent scene, kept so a lookup landing later can still be answered from it. */
	private final Set<Integer> lastScene = ConcurrentHashMap.newKeySet();
	/** Furniture name to the object ids it places, looked up from the wiki once per name. */
	private final Map<String, Set<Integer>> objectIds = new ConcurrentHashMap<>();
	private final Set<String> beingLookedUp = ConcurrentHashMap.newKeySet();
	private Runnable onResolved;

	/**
	 * @return true if the scene looked like a house and was recorded.
	 */
	boolean scanScene()
	{
		// Building mode is the only thing the client exposes that means "this is your own house"
		// and nowhere else. Other instances - raids, minigames - would otherwise be scanned too,
		// and there's no reliable way to tell a house from them once you're just standing in one.
		// The cost is that furniture is only recorded on visits made in building mode.
		if (client.getVarbitValue(VarbitID.POH_BUILDING_MODE) == 0)
		{
			return false;
		}

		Set<Integer> found = new HashSet<>();

		Scene scene = client.getTopLevelWorldView().getScene();
		for (Tile[][] plane : scene.getTiles())
		{
			for (Tile[] column : plane)
			{
				for (Tile tile : column)
				{
					if (tile == null)
					{
						continue;
					}

					for (TileObject object : objectsOn(tile))
					{
						if (object != null)
						{
							found.add(object.getId());
						}
					}
				}
			}
		}

		if (found.isEmpty())
		{
			return false;
		}

		load();
		// Accumulated rather than replaced: only the loaded part of the house is in the scene, so
		// a scan taken in one corner shouldn't erase what was seen in another.
		lastScene.clear();
		lastScene.addAll(found);
		return remember(found);
	}

	/**
	 * @return true once we've seen the furniture's objects in the house, null while we can't say.
	 *
	 * Never returns false. Not finding it doesn't mean it isn't there: only the loaded part of
	 * the house is visible, the player may not have gone inside yet, and an upgrade past this
	 * tier replaces the object with a different one - all of which would read as "missing".
	 * Callers get a positive confirmation or nothing.
	 */
	Boolean isBuilt(String furnitureName)
	{
		Set<Integer> ids = objectIds.get(furnitureName);
		if (ids == null)
		{
			lookUp(furnitureName);
			return null;
		}

		load();
		return !ids.isEmpty() && !Collections.disjoint(seen, ids) ? Boolean.TRUE : null;
	}

	/**
	 * The wiki knows which objects a build places - the in-game object is often named differently
	 * from the build ("Rejuvenation pool" places "Pool of Rejuvenation"), so its ids are the only
	 * dependable link between the two.
	 */
	private void lookUp(String furnitureName)
	{
		if (!beingLookedUp.add(furnitureName))
		{
			return;
		}

		wikiRecipeService.fetchObjectIds(furnitureName, ids ->
		{
			objectIds.put(furnitureName, ids);
			beingLookedUp.remove(furnitureName);

			// The scene was scanned before we knew these ids mattered, so check it again now.
			remember(lastScene);
			if (onResolved != null)
			{
				onResolved.run();
			}
		});
	}

	/**
	 * Keeps only what some prerequisite actually asks about. A scene holds hundreds of objects and
	 * almost none of them are furniture we'll ever be asked about, so storing the lot would bloat
	 * the saved config for nothing.
	 *
	 * @return true if anything worth remembering was found.
	 */
	private boolean remember(Set<Integer> found)
	{
		Set<Integer> interesting = new HashSet<>();
		for (Set<Integer> ids : objectIds.values())
		{
			interesting.addAll(ids);
		}
		interesting.retainAll(found);

		load();
		if (interesting.isEmpty() || !seen.addAll(interesting))
		{
			return false;
		}

		configManager.setRSProfileConfiguration(MaterialsManager.CONFIG_GROUP, CONFIG_KEY,
			seen.stream().map(String::valueOf).collect(Collectors.joining(",")));
		log.debug("Required materials: house now known to contain {}", seen);
		return true;
	}

	/** Set by the plugin so the panel can repaint once a lookup lands. */
	void onResolved(Runnable onResolved)
	{
		this.onResolved = onResolved;
	}

	private List<TileObject> objectsOn(Tile tile)
	{
		List<TileObject> objects = new ArrayList<>();
		Collections.addAll(objects, tile.getGameObjects());
		objects.add(tile.getWallObject());
		objects.add(tile.getDecorativeObject());
		objects.add(tile.getGroundObject());
		return objects;
	}

	private void load()
	{
		// Re-reads while empty: per-account config isn't readable until logged in, so an empty
		// first read means "not available yet" rather than "nothing stored".
		if (seen != null && !seen.isEmpty())
		{
			return;
		}

		seen = new HashSet<>();
		String stored = configManager.getRSProfileConfiguration(MaterialsManager.CONFIG_GROUP, CONFIG_KEY);
		if (stored == null || stored.isEmpty())
		{
			return;
		}

		for (String id : stored.split(","))
		{
			try
			{
				seen.add(Integer.parseInt(id.trim()));
			}
			catch (NumberFormatException ignored)
			{
				// A hand-edited value shouldn't stop the rest loading.
			}
		}
	}
}

package com.requiredmaterials;

import java.util.regex.Matcher;
import java.util.regex.Pattern;
import net.runelite.api.Client;
import net.runelite.api.Skill;

/**
 * Level requirements are carried around as text ("Level 20 Sailing") because that's how they're
 * shown; this reads one back well enough to check it against the player.
 */
final class LevelRequirement
{
	private static final Pattern PATTERN = Pattern.compile("^Level (\\d+) (.+)$", Pattern.CASE_INSENSITIVE);

	private LevelRequirement()
	{
	}

	/**
	 * @return the level, or -1 if this isn't a recognisable "Level N Skill".
	 */
	static int levelIn(String requirement)
	{
		Matcher matcher = PATTERN.matcher(requirement);
		return matcher.matches() ? Integer.parseInt(matcher.group(1)) : -1;
	}

	/**
	 * @return the skill named, or null if it isn't parseable or isn't a real skill.
	 */
	static Skill skillIn(String requirement)
	{
		Matcher matcher = PATTERN.matcher(requirement);
		if (!matcher.matches())
		{
			return null;
		}

		return named(matcher.group(2).trim());
	}

	/**
	 * @return the skill with this exact name, or null - e.g. "Other", the bucket used for
	 * requirements tracked before the source skill was recorded.
	 */
	static Skill named(String name)
	{
		for (Skill skill : Skill.values())
		{
			if (skill.getName().equalsIgnoreCase(name))
			{
				return skill;
			}
		}
		return null;
	}

	/**
	 * @return true if the player meets it, or if it isn't a recognisable requirement - something
	 * unparseable shouldn't read as one the player has failed.
	 */
	static boolean isMet(Client client, String requirement)
	{
		Skill skill = skillIn(requirement);
		return skill == null || client.getRealSkillLevel(skill) >= levelIn(requirement);
	}
}

package com.requiredmaterials;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import com.google.gson.reflect.TypeToken;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.game.ItemManager;
import net.runelite.http.api.item.ItemPrice;

/**
 * Keeps a running set of tracked requirements (keyed by part name so re-tracking one just
 * replaces it), resolves item names to ids, and persists across sessions. Materials and level
 * requirements arrive already resolved from the caller - this class only handles storage.
 */
@Slf4j
@Singleton
public class MaterialsManager
{
	static final String CONFIG_GROUP = "requiredmaterials";
	private static final String CONFIG_KEY_TRACKED = "tracked";

	private static final Type SAVE_TYPE =
		new TypeToken<LinkedHashMap<String, SavedRequirement>>()
		{
		}.getType();

	private static final int MAX_ITEM_ID_SCAN = 35000;

	@Inject
	private Client client;

	@Inject
	private ConfigManager configManager;

	@Inject
	private ItemManager itemManager;

	@Inject
	private HeldItems heldItems;

	@Inject
	private Gson gson;

	private final Map<String, TrackedRequirement> requirements = new LinkedHashMap<>();
	private Map<String, Integer> fullItemNameIndex;

	public void track(String partName, Map<String, Integer> materialQuantities, List<String> levelRequirements)
	{
		track(partName, materialQuantities, levelRequirements, Collections.emptySet(), true);
	}

	public void track(String partName, Map<String, Integer> materialQuantities, List<String> levelRequirements, boolean moveToBottom)
	{
		track(partName, materialQuantities, levelRequirements, Collections.emptySet(), moveToBottom);
	}

	/**
	 * @param moveToBottom whether re-tracking should reorder the list. True when the player picks
	 * something out again, which is a fresh expression of interest; false when they click Build,
	 * where they're acting on the part rather than re-prioritising it.
	 */
	public void track(String partName, Map<String, Integer> materialQuantities, List<String> levelRequirements,
		Set<String> prerequisites, boolean moveToBottom)
	{
		List<RequiredMaterial> materials = new ArrayList<>();
		for (Map.Entry<String, Integer> entry : materialQuantities.entrySet())
		{
			RequiredMaterial material = new RequiredMaterial(entry.getKey(), entry.getValue());
			material.setItemId(resolveItemId(entry.getKey()));
			materials.add(material);
		}

		TrackedRequirement requirement = new TrackedRequirement(partName, materials);
		requirement.setLevelRequirements(levelRequirements);
		requirement.setPrerequisites(new ArrayList<>(prerequisites));

		// A re-put keeps the key's original position, so moving to the bottom needs an explicit
		// remove first.
		if (moveToBottom)
		{
			requirements.remove(partName);
		}
		requirements.put(partName, requirement);
		save();
	}

	/**
	 * Whether the player could build this right now - every material to hand and every level met.
	 * A material whose name doesn't resolve to an item counts as missing, since we can't count
	 * something we can't identify.
	 */
	boolean canBuild(Map<String, Integer> materials, List<String> levelRequirements)
	{
		for (Map.Entry<String, Integer> material : materials.entrySet())
		{
			// Inventory only: a build consumes what you're carrying, so materials sitting in the
			// bank don't make it buildable.
			Integer itemId = resolveItemId(material.getKey());
			if (itemId == null || heldItems.inInventory(itemId) < material.getValue())
			{
				return false;
			}
		}

		for (String requirement : levelRequirements)
		{
			if (!LevelRequirement.isMet(client, requirement))
			{
				return false;
			}
		}

		return true;
	}

	private Integer resolveItemId(String itemName)
	{
		// ItemManager#search only covers GE-tradeable items, so non-tradeable materials never
		// show up in it - the full item-definition scan below covers those.
		List<ItemPrice> results = itemManager.search(itemName);
		for (ItemPrice result : results)
		{
			if (result.getName().equalsIgnoreCase(itemName))
			{
				return result.getId();
			}
		}

		// getItemDefinition asserts it's on the client thread; callers off it skip the fallback
		// rather than crashing.
		if (client.isClientThread())
		{
			Integer fullIndexMatch = fullItemNameIndex().get(itemName.toLowerCase());
			if (fullIndexMatch != null)
			{
				return fullIndexMatch;
			}
		}

		if (!results.isEmpty())
		{
			log.debug("Required materials: no exact name match for '{}', falling back to closest search result '{}'",
				itemName, results.get(0).getName());
			return results.get(0).getId();
		}

		log.warn("Required materials: could not resolve item id for '{}' - it won't be highlightable in the bank", itemName);
		return null;
	}

	private Map<String, Integer> fullItemNameIndex()
	{
		if (fullItemNameIndex != null)
		{
			return fullItemNameIndex;
		}

		Map<String, Integer> index = new HashMap<>();
		for (int id = 0; id < MAX_ITEM_ID_SCAN; id++)
		{
			ItemComposition composition = client.getItemDefinition(id);
			String name = composition.getName();
			if (name == null || name.isEmpty() || "null".equals(name))
			{
				continue;
			}
			index.putIfAbsent(name.toLowerCase(), composition.getId());
		}

		fullItemNameIndex = index;
		return index;
	}

	public Collection<TrackedRequirement> getRequirements()
	{
		return requirements.values();
	}

	public void setSkill(String partName, String skill)
	{
		TrackedRequirement requirement = requirements.get(partName);
		if (requirement != null)
		{
			requirement.setSkill(skill);
			save();
		}
	}

	public void remove(String partName)
	{
		if (requirements.remove(partName) != null)
		{
			save();
		}
	}

	public void clear()
	{
		requirements.clear();
		save();
	}

	public boolean isEmpty()
	{
		return requirements.isEmpty();
	}

	public void save()
	{
		Map<String, SavedRequirement> toSave = new LinkedHashMap<>();
		for (TrackedRequirement requirement : requirements.values())
		{
			List<SavedMaterial> materials = requirement.getMaterials().stream()
				.map(m -> new SavedMaterial(m.getName(), m.getQuantity()))
				.collect(Collectors.toList());
			toSave.put(requirement.getPartName(), new SavedRequirement(materials, requirement.getLevelRequirements(), requirement.getSkill(), requirement.getPrerequisites()));
		}
		configManager.setConfiguration(CONFIG_GROUP, CONFIG_KEY_TRACKED, gson.toJson(toSave));
	}

	public void load()
	{
		String json = configManager.getConfiguration(CONFIG_GROUP, CONFIG_KEY_TRACKED);
		if (json == null || json.isEmpty())
		{
			return;
		}

		Map<String, SavedRequirement> saved;
		try
		{
			saved = gson.fromJson(json, SAVE_TYPE);
		}
		catch (JsonSyntaxException e)
		{
			log.warn("Required materials: discarding unreadable saved config", e);
			return;
		}

		if (saved == null)
		{
			return;
		}

		requirements.clear();
		for (Map.Entry<String, SavedRequirement> entry : saved.entrySet())
		{
			List<RequiredMaterial> materials = new ArrayList<>();
			for (SavedMaterial savedMaterial : entry.getValue().materials)
			{
				RequiredMaterial material = new RequiredMaterial(savedMaterial.name, savedMaterial.quantity);
				material.setItemId(resolveItemId(savedMaterial.name));
				materials.add(material);
			}
			TrackedRequirement requirement = new TrackedRequirement(entry.getKey(), materials);
			if (entry.getValue().levelRequirements != null)
			{
				requirement.setLevelRequirements(entry.getValue().levelRequirements);
			}
			requirement.setSkill(entry.getValue().skill);
			if (entry.getValue().prerequisites != null)
			{
				requirement.setPrerequisites(entry.getValue().prerequisites);
			}
			requirements.put(entry.getKey(), requirement);
		}
	}

	private static class SavedRequirement
	{
		List<SavedMaterial> materials;
		List<String> levelRequirements;
		String skill;
		List<String> prerequisites;

		SavedRequirement(List<SavedMaterial> materials, List<String> levelRequirements, String skill, List<String> prerequisites)
		{
			this.materials = materials;
			this.levelRequirements = levelRequirements;
			this.skill = skill;
			this.prerequisites = prerequisites;
		}
	}

	private static class SavedMaterial
	{
		String name;
		int quantity;

		SavedMaterial(String name, int quantity)
		{
			this.name = name;
			this.quantity = quantity;
		}
	}
}

package com.requiredmaterials;

import java.util.Locale;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * Sailing part naming, shared by the panel (which parts share a card) and the plugin (which wiki
 * page to fetch) - they have to agree or a part groups under a name nothing looked up.
 *
 * Skill-agnostic on purpose: "(beginner)" in a Construction name isn't a boat size, so callers
 * gate on skill first.
 */
final class PartNames
{
	private static final Pattern VARIANT_SUFFIX = Pattern.compile("\\s*\\(([^)]*)\\)$");
	private static final String BASE = "base";
	private static final String HULL = "hull";

	private PartNames()
	{
	}

	/** "Oak hull (skiff)" -> "Oak hull". */
	static String withoutVariant(String partName)
	{
		return VARIANT_SUFFIX.matcher(partName).replaceFirst("").trim();
	}

	/** "Oak hull (skiff)" -> "Skiff", null when unsuffixed. */
	static String variantOf(String partName)
	{
		Matcher matcher = VARIANT_SUFFIX.matcher(partName);
		if (!matcher.find())
		{
			return null;
		}
		String variant = matcher.group(1).trim();
		return variant.isEmpty() ? null : capitalize(variant);
	}

	/** Raft parts carry no suffix - they're just "&lt;tier&gt; base". */
	static String boatSizeOf(String partName)
	{
		String variant = variantOf(partName);
		if (variant != null)
		{
			return variant;
		}
		return isBase(partName) ? "Raft" : null;
	}

	/** A raft's "base" and a skiff's "hull" are one slot, filed under "hull" on the wiki. */
	static String sharedName(String partName)
	{
		String withoutVariant = withoutVariant(partName);
		return isBase(withoutVariant)
			? withoutVariant.substring(0, withoutVariant.length() - BASE.length()) + HULL
			: withoutVariant;
	}

	static String capitalize(String s)
	{
		return s.isEmpty() ? s : Character.toUpperCase(s.charAt(0)) + s.substring(1);
	}

	private static boolean isBase(String partName)
	{
		return partName.toLowerCase(Locale.ROOT).endsWith(BASE);
	}
}

