package com.requiredmaterials;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Component;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.GridBagConstraints;
import java.awt.GridBagLayout;
import java.awt.Insets;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.ImageIcon;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JTextArea;
import net.runelite.api.Client;
import net.runelite.api.ItemContainer;
import net.runelite.api.Skill;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;

/**
 * Sidebar panel listing what's currently tracked, in a collapsible section per skill.
 *
 * Boat-size variants of the same part - "(raft)"/"(skiff)"/"(sloop)", or a raft's "base" vs a
 * skiff/sloop's "hull" - are tracked separately but share one card with a picker.
 */
public class RequiredMaterialsPanel extends PluginPanel
{
	private static final Color COLOR_READY = new Color(96, 220, 96);
	private static final Color COLOR_IN_BANK = Color.WHITE;
	private static final Pattern LEVEL_REQUIREMENT_PATTERN = Pattern.compile("^Level (\\d+) (.+)$", Pattern.CASE_INSENSITIVE);
	private static final Pattern VARIANT_SUFFIX = Pattern.compile("^(.*?)\\s*\\(([^)]*)\\)$");
	private static final String UNKNOWN_SKILL = "Other";

	private final MaterialsManager materialsManager;
	private final Client client;
	private final ClientThread clientThread;
	private final SkillIconManager skillIconManager;
	private final HeldItems heldItems;
	private final HouseContents houseContents;
	private final JPanel listContainer = new JPanel();
	private final Map<String, Integer> selectedVariantIndex = new HashMap<>();
	private final Map<String, Boolean> skillExpanded = new HashMap<>();

	RequiredMaterialsPanel(MaterialsManager materialsManager, Client client, ClientThread clientThread, SkillIconManager skillIconManager, HeldItems heldItems, HouseContents houseContents)
	{
		this.materialsManager = materialsManager;
		this.client = client;
		this.clientThread = clientThread;
		this.skillIconManager = skillIconManager;
		this.heldItems = heldItems;
		this.houseContents = houseContents;

		setLayout(new BorderLayout(0, 8));
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		JLabel title = new JLabel("Required Materials");
		title.setForeground(ColorScheme.BRAND_ORANGE);

		JButton clearAll = new JButton("Clear all");
		clearAll.addActionListener(e -> clientThread.invoke(() ->
		{
			materialsManager.clear();
			skillExpanded.clear();
			refresh();
		}));

		JPanel header = new JPanel(new BorderLayout());
		header.add(title, BorderLayout.WEST);
		header.add(clearAll, BorderLayout.EAST);

		JPanel top = new JPanel();
		top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));
		top.add(header);

		listContainer.setLayout(new BoxLayout(listContainer, BoxLayout.Y_AXIS));

		add(top, BorderLayout.NORTH);
		add(listContainer, BorderLayout.CENTER);
	}

	/**
	 * Opens the tracked skill's section. A skill appearing for the first time collapses the
	 * others, so a switch of skill leaves only the new one open; re-tracking a skill already on
	 * the list just reopens it and leaves the rest alone.
	 */
	void onTracked(String skill)
	{
		if (!skillExpanded.containsKey(skill))
		{
			skillExpanded.replaceAll((s, expanded) -> false);
		}
		skillExpanded.put(skill, true);
		refresh();
	}

	void refresh()
	{
		listContainer.removeAll();

		if (materialsManager.isEmpty())
		{
			listContainer.add(wrappedText(
				"Nothing tracked yet. Open the Construction or Sailing skill guide and click on a piece of furniture or ship facility to start tracking the required materials. You can also start tracking required materials from the Furniture Creation or the Boat Customisation menus.",
				ColorScheme.LIGHT_GRAY_COLOR));
		}
		else
		{
			if (!heldItems.bankKnown())
			{
				listContainer.add(wrappedText(
					"Open your bank to update the tracked required materials.",
					ColorScheme.LIGHT_GRAY_COLOR));
				listContainer.add(Box.createVerticalStrut(6));
			}

			if (hasUnconfirmedPrerequisite())
			{
				listContainer.add(wrappedText(
					"Visit your POH in building mode to check what's already built.",
					ColorScheme.LIGHT_GRAY_COLOR));
				listContainer.add(Box.createVerticalStrut(6));
			}

			// getRequirements() is in tracking order, so a skill's highest position is the last
			// time anything was tracked under it.
			Map<String, List<TrackedRequirement>> byPart = new LinkedHashMap<>();
			Map<String, Integer> lastTrackedAt = new HashMap<>();
			int position = 0;
			for (TrackedRequirement requirement : materialsManager.getRequirements())
			{
				byPart.computeIfAbsent(PartNames.sharedName(requirement.getPartName()), k -> new ArrayList<>())
					.add(requirement);
				lastTrackedAt.put(skillOf(requirement), position++);
			}

			Map<String, List<Map.Entry<String, List<TrackedRequirement>>>> bySkill = new LinkedHashMap<>();
			for (Map.Entry<String, List<TrackedRequirement>> entry : byPart.entrySet())
			{
				bySkill.computeIfAbsent(skillOf(entry.getValue().get(0)), k -> new ArrayList<>()).add(entry);
			}

			List<String> orderedSkills = new ArrayList<>(bySkill.keySet());
			orderedSkills.sort(Comparator.comparingInt((String skill) -> lastTrackedAt.getOrDefault(skill, -1)).reversed());

			boolean firstShown = true;
			for (String skill : orderedSkills)
			{
				listContainer.add(buildAccordion(skill, bySkill.get(skill), firstShown));
				listContainer.add(Box.createVerticalStrut(6));
				firstShown = false;
			}
		}

		listContainer.revalidate();
		listContainer.repaint();
	}

	/**
	 * Whether anything is waiting on a look inside the house - the hint is pointless once every
	 * prerequisite is confirmed, and misleading when nothing has any.
	 */
	private boolean hasUnconfirmedPrerequisite()
	{
		for (TrackedRequirement requirement : materialsManager.getRequirements())
		{
			for (String prerequisite : requirement.getPrerequisites())
			{
				if (!Boolean.TRUE.equals(houseContents.isBuilt(prerequisite)))
				{
					return true;
				}
			}
		}
		return false;
	}

	private JPanel buildAccordion(String skill, List<Map.Entry<String, List<TrackedRequirement>>> groups, boolean defaultExpanded)
	{
		boolean expanded = skillExpanded.computeIfAbsent(skill, k -> defaultExpanded);

		JLabel arrow = new JLabel(expanded ? "-" : "+");
		arrow.setForeground(ColorScheme.LIGHT_GRAY_COLOR);
		arrow.setFont(arrow.getFont().deriveFont(Font.BOLD));
		arrow.setPreferredSize(new Dimension(12, arrow.getPreferredSize().height));

		JLabel skillLabel = new JLabel(skill);
		skillLabel.setForeground(ColorScheme.BRAND_ORANGE);
		skillLabel.setFont(skillLabel.getFont().deriveFont(Font.BOLD));

		Skill skillEnum = LevelRequirement.named(skill);
		JLabel skillIcon = skillEnum != null
			? new JLabel(new ImageIcon(skillIconManager.getSkillImage(skillEnum, true)))
			: null;

		JPanel headerLabels = new JPanel();
		headerLabels.setLayout(new BoxLayout(headerLabels, BoxLayout.X_AXIS));
		headerLabels.setOpaque(false);
		headerLabels.add(arrow);
		headerLabels.add(Box.createHorizontalStrut(6));
		if (skillIcon != null)
		{
			headerLabels.add(skillIcon);
			headerLabels.add(Box.createHorizontalStrut(4));
		}
		headerLabels.add(skillLabel);

		JPanel header = new JPanel(new BorderLayout());
		header.setOpaque(true);
		header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		header.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		header.add(headerLabels, BorderLayout.WEST);
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		header.setAlignmentX(Component.LEFT_ALIGNMENT);

		MouseAdapter toggleListener = new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				clientThread.invoke(() ->
				{
					skillExpanded.put(skill, !skillExpanded.getOrDefault(skill, defaultExpanded));
					refresh();
				});
			}
		};
		for (Component c : new Component[] {header, headerLabels, arrow, skillLabel, skillIcon})
		{
			if (c != null)
			{
				c.addMouseListener(toggleListener);
			}
		}

		JPanel wrapper = new JPanel(new GridBagLayout());
		wrapper.setOpaque(false);
		wrapper.setAlignmentX(Component.LEFT_ALIGNMENT);

		GridBagConstraints gbc = new GridBagConstraints();
		gbc.gridx = 0;
		gbc.gridy = 0;
		gbc.weightx = 1.0;
		gbc.fill = GridBagConstraints.HORIZONTAL;
		wrapper.add(header, gbc);

		if (expanded)
		{
			for (Map.Entry<String, List<TrackedRequirement>> entry : groups)
			{
				List<TrackedRequirement> variants = entry.getValue();
				gbc.gridy++;
				gbc.insets = new Insets(6, 0, 0, 0);
				wrapper.add(variants.size() > 1
					? buildOuterCard(PartNames.capitalize(entry.getKey()), variants, buildVariantSection(entry.getKey(), variants))
					: buildOuterCard(variants.get(0).getPartName(), variants, buildContent(variants.get(0))), gbc);
			}
		}

		return wrapper;
	}

	private String skillOf(TrackedRequirement requirement)
	{
		return requirement.getSkill() != null ? requirement.getSkill() : UNKNOWN_SKILL;
	}

	private JPanel buildOuterCard(String title, List<TrackedRequirement> allInside, JPanel content)
	{
		JPanel card = new JPanel(new BorderLayout(0, 4));
		card.setBackground(ColorScheme.DARKER_GRAY_COLOR);
		card.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));

		// Wraps rather than truncating: the panel is narrow, and narrower still once a scrollbar
		// appears, which was enough to cut "Oak chest of drawers" down to "Oak chest of dr...".
		JTextArea name = wrappedText(title, ColorScheme.BRAND_ORANGE);

		JButton remove = new JButton("x");
		remove.setMargin(new java.awt.Insets(0, 4, 0, 4));
		remove.addActionListener(e -> clientThread.invoke(() ->
		{
			for (TrackedRequirement requirement : allInside)
			{
				materialsManager.remove(requirement.getPartName());
			}
			refresh();
		}));

		JPanel cardHeader = new JPanel(new BorderLayout());
		cardHeader.setOpaque(false);
		cardHeader.add(name, BorderLayout.CENTER);
		cardHeader.add(remove, BorderLayout.EAST);

		card.add(cardHeader, BorderLayout.NORTH);
		card.add(content, BorderLayout.CENTER);
		return card;
	}

	private JPanel buildVariantSection(String selectionKey, List<TrackedRequirement> variants)
	{
		JComboBox<String> variantPicker = new JComboBox<>();
		for (TrackedRequirement variant : variants)
		{
			variantPicker.addItem(boatSize(variant.getPartName()));
		}
		int savedIndex = selectedVariantIndex.getOrDefault(selectionKey, 0);
		if (savedIndex >= variants.size())
		{
			savedIndex = 0;
		}
		variantPicker.setSelectedIndex(savedIndex);

		JPanel pickerRow = new JPanel(new BorderLayout());
		pickerRow.setOpaque(false);
		pickerRow.setAlignmentX(Component.LEFT_ALIGNMENT);
		pickerRow.add(variantPicker, BorderLayout.WEST);

		JPanel section = new JPanel();
		section.setLayout(new BoxLayout(section, BoxLayout.Y_AXIS));
		section.setOpaque(false);
		section.add(pickerRow);
		section.add(Box.createVerticalStrut(4));
		section.add(buildContent(variants.get(savedIndex)));

		// refresh() reads bank/skill state, which asserts it's on the client thread - Swing
		// listeners fire on the AWT event thread.
		variantPicker.addActionListener(e -> clientThread.invoke(() ->
		{
			selectedVariantIndex.put(selectionKey, variantPicker.getSelectedIndex());
			refresh();
		}));

		return section;
	}

	/** Falls back to the whole name so a picker never shows a blank entry. */
	private String boatSize(String partName)
	{
		String size = PartNames.boatSizeOf(partName);
		return size != null ? size : partName;
	}

	private JPanel buildContent(TrackedRequirement requirement)
	{
		JPanel content = new JPanel();
		content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
		content.setOpaque(false);
		content.setAlignmentX(Component.LEFT_ALIGNMENT);

		if (!requirement.getLevelRequirements().isEmpty() || !requirement.getPrerequisites().isEmpty())
		{
			for (String levelRequirement : requirement.getLevelRequirements())
			{
				content.add(buildLevelRequirementLine(levelRequirement));
			}
			for (String prerequisite : requirement.getPrerequisites())
			{
				// Green once we've seen it in the house; grey while we can't say, which covers
				// both "not built" and "haven't been inside yet".
				Color color = Boolean.TRUE.equals(houseContents.isBuilt(prerequisite))
					? COLOR_READY
					: ColorScheme.LIGHT_GRAY_COLOR;
				content.add(wrappedText("Requires: " + prerequisite + " built", color));
			}
			content.add(Box.createVerticalStrut(6));
			content.add(divider());
			content.add(Box.createVerticalStrut(6));
		}

		if (requirement.getMaterials().isEmpty())
		{
			content.add(wrappedText("No materials required.", ColorScheme.LIGHT_GRAY_COLOR));
		}
		else
		{
			for (RequiredMaterial material : requirement.getMaterials())
			{
				content.add(buildMaterialLine(material));
			}
		}

		return content;
	}

	private JTextArea buildLevelRequirementLine(String levelRequirement)
	{
		Color color = LevelRequirement.isMet(client, levelRequirement)
			? COLOR_READY
			: ColorScheme.LIGHT_GRAY_COLOR;
		return wrappedText("Requires: " + levelRequirement, color);
	}

	private JTextArea buildMaterialLine(RequiredMaterial material)
	{
		if (material.getItemId() == null)
		{
			String text = material.getQuantity() + "x " + material.getName() + " (couldn't find a matching item)";
			return wrappedText(text, ColorScheme.PROGRESS_ERROR_COLOR);
		}

		int inInventory = heldItems.inInventory(material.getItemId());
		int have = heldItems.inBank(material.getItemId()) + inInventory;
		int need = material.getQuantity();

		// Green means you can build now, white means you own enough but it's still banked. Short
		// of that it's grey, which also covers not having opened a bank yet.
		Color color;
		if (inInventory >= need)
		{
			color = COLOR_READY;
		}
		else if (have >= need)
		{
			color = COLOR_IN_BANK;
		}
		else
		{
			color = ColorScheme.LIGHT_GRAY_COLOR;
		}

		String text = material.getName() + " (" + have + "/" + need + ")";
		return wrappedText(text, color);
	}

	private JPanel divider()
	{
		JPanel line = new JPanel();
		line.setBackground(ColorScheme.MEDIUM_GRAY_COLOR);
		line.setMaximumSize(new Dimension(Integer.MAX_VALUE, 1));
		line.setPreferredSize(new Dimension(Integer.MAX_VALUE, 1));
		line.setAlignmentX(Component.LEFT_ALIGNMENT);
		return line;
	}

	/**
	 * A JTextArea rather than a JLabel: JLabel's HTML "width:Npx" wrapping clips instead of
	 * reflowing when the sidebar's real width doesn't match the hardcoded pixel value.
	 */
	private JTextArea wrappedText(String text, Color color)
	{
		JTextArea area = new JTextArea(text);
		area.setEditable(false);
		area.setFocusable(false);
		area.setLineWrap(true);
		area.setWrapStyleWord(true);
		area.setOpaque(false);
		area.setForeground(color);
		area.setFont(new JLabel().getFont());
		area.setBorder(null);
		area.setMaximumSize(new Dimension(Integer.MAX_VALUE, Integer.MAX_VALUE));
		// JComponent defaults to centre alignment. In a BoxLayout that mixes it with the
		// left-aligned rows, everything is laid out against a wider virtual width and the rows
		// end up half the panel.
		area.setAlignmentX(Component.LEFT_ALIGNMENT);
		return area;
	}
}

package com.requiredmaterials;

import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import com.google.inject.Provides;
import javax.inject.Inject;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.ChatMessageType;
import net.runelite.api.GameState;
import net.runelite.api.Client;
import net.runelite.api.events.ChatMessage;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.MenuOptionClicked;
import net.runelite.api.events.ScriptPostFired;
import net.runelite.api.events.ScriptPreFired;
import net.runelite.api.events.StatChanged;
import net.runelite.api.events.WidgetClosed;
import net.runelite.api.events.WidgetLoaded;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.game.SkillIconManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;

@Slf4j
@PluginDescriptor(
	name = "Required Materials",
	description = "Tracks the materials and levels you still need for Sailing and Construction builds, and groups them in your bank",
	tags = {"sailing", "construction", "materials", "bank", "skilling", "shipwright"}
)
public class RequiredMaterialsPlugin extends Plugin
{
	private static final List<String> TRACKED_SKILLS = Arrays.asList("Sailing", "Construction");
	private static final Pattern PART_NAME_PATTERN = Pattern.compile("^(.*?):");
	private static final Pattern TAG_PATTERN = Pattern.compile("<[^>]*>");
	// "Check Materials" labels the part "Camphor hull materials"; every other trigger just says
	// "Camphor hull", which is also the wiki page name.
	private static final Pattern MATERIALS_SUFFIX = Pattern.compile("(?i)\\s+materials$");
	private static final int HOUSE_SCAN_DELAY_TICKS = 6;

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private MaterialsManager materialsManager;

	@Inject
	private WikiRecipeService wikiRecipeService;

	@Inject
	private BankSnapshot bankSnapshot;

	@Inject
	private HeldItems heldItems;

	@Inject
	private HouseContents houseContents;

	@Inject
	private RequiredMaterialsConfig config;

	@Inject
	private BankButtonManager bankButtonManager;

	@Inject
	private BankGroupedView bankGroupedView;

	@Inject
	private SkillIconManager skillIconManager;

	private final ChatMaterialsParser chatMaterialsParser = new ChatMaterialsParser();
	private final GuideLevelReader guideLevelReader = new GuideLevelReader();

	private RequiredMaterialsPanel panel;
	private NavigationButton navButton;
	private boolean shipCustomisationOpen;
	private boolean furnitureCreationOpen;
	private String lastKnownGuideV2Title;
	private String lastKnownGuideV1Title;
	private String pendingContinuationPartName;
	private int ticksSinceSceneLoad = -1;

	@Provides
	RequiredMaterialsConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(RequiredMaterialsConfig.class);
	}

	@Override
	protected void startUp()
	{
		panel = new RequiredMaterialsPanel(materialsManager, client, clientThread, skillIconManager, heldItems, houseContents);

		// load() resolves item ids, which must happen on the client thread - startUp() isn't
		// guaranteed to be on it (e.g. toggled from the config UI).
		houseContents.onResolved(() -> clientThread.invoke(() ->
		{
			if (panel != null)
			{
				panel.refresh();
			}
		}));

		clientThread.invoke(() ->
		{
			materialsManager.load();
			panel.refresh();
		});

		navButton = NavigationButton.builder()
			.tooltip("Required Materials")
			.icon(ImageUtil.loadImageResource(getClass(), "icon.png"))
			.priority(6)
			.panel(panel)
			.build();
		clientToolbar.addNavigation(navButton);
	}

	@Override
	protected void shutDown()
	{
		clientToolbar.removeNavigation(navButton);
		panel = null;
		navButton = null;
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (event.getType() != ChatMessageType.GAMEMESSAGE && event.getType() != ChatMessageType.SPAM)
		{
			return;
		}

		if (!shipCustomisationOpen && !isTrackedSkillGuideOpen())
		{
			return;
		}

		String message = event.getMessage();
		if (message == null)
		{
			return;
		}

		Matcher matcher = PART_NAME_PATTERN.matcher(message);
		if (matcher.find())
		{
			String partName = MATERIALS_SUFFIX.matcher(
				TAG_PATTERN.matcher(matcher.group(1)).replaceAll("").replace('\u00A0', ' ').trim()
			).replaceFirst("");
			if (partName.isEmpty())
			{
				return;
			}

			// Accumulated only as a fallback for Construction activities the wiki has no
			// {{Recipe}} for (Mahogany Homes, Birdhouses, STASH units); the wiki stays primary.
			String materialsText = message.substring(matcher.end()).trim();
			pendingContinuationPartName = chatMaterialsParser.accumulate(partName, materialsText) ? partName : null;

			trackFromWiki(partName, currentSkillSource(), false);
		}
		else if (pendingContinuationPartName != null)
		{
			pendingContinuationPartName = chatMaterialsParser.appendContinuation(pendingContinuationPartName, message)
				? pendingContinuationPartName : null;
		}
	}

	@Subscribe(priority = -1)
	public void onMenuOptionClicked(MenuOptionClicked event)
	{
		bankGroupedView.onMenuOptionClicked(event);

		if (!"Build".equals(event.getMenuOption()))
		{
			return;
		}

		String partName = TAG_PATTERN.matcher(event.getMenuTarget()).replaceAll("").trim();
		if (furnitureCreationOpen)
		{
			trackFromWiki(partName, "Construction", true);
		}
		else if (shipCustomisationOpen)
		{
			trackFromWiki(partName, "Sailing", true);
		}
	}

	/**
	 * Looks the part up on the wiki, falling back to chat/guide-widget data for Construction
	 * items with no recipe there. The wiki callback runs off the client thread, so tracking
	 * hops back onto it.
	 */
	private void trackFromWiki(String partName, String skill, boolean buildClick)
	{
		List<String> pageNames = wikiPageCandidates(partName, skill);
		String variant = wikiVariant(partName, skill);

		wikiRecipeService.fetchRecipes(pageNames, recipes ->
		{
			WikiRecipeService.Recipe recipe = selectRecipe(recipes, variant);

			clientThread.invoke(() ->
			{
				if (buildClick && recipe != null
					&& materialsManager.canBuild(recipe.getMaterials(), recipe.getLevelRequirements())
					&& handleBuiltWhatTheyHad(partName))
				{
					return;
				}

				boolean tracked;
				if (recipe != null)
				{
					materialsManager.track(partName, recipe.getMaterials(), recipe.getLevelRequirements(), recipe.getPrerequisites(), !buildClick);
					tracked = true;
				}
				else
				{
					tracked = "Construction".equals(skill) && trackFromChatFallback(partName, !buildClick);
				}

				if (!tracked)
				{
					log.warn("Required materials: could not resolve requirements for '{}' (tried {})", partName, pageNames);
					return;
				}

				materialsManager.setSkill(partName, skill);
				if (panel != null)
				{
					panel.onTracked(skill);
				}
			});
		});
	}

	/**
	 * Clicking Build with everything already to hand means it's built, so there's nothing left to
	 * collect for it. Clicking Build isn't proof the build finished - it can still be cancelled -
	 * but having every material and level is the closest signal the client gives.
	 *
	 * Clearing wins over tracking when both settings are on: removing it and then adding it
	 * straight back would leave it on the list anyway, just reordered.
	 *
	 * @return true if this build shouldn't be tracked.
	 */
	private boolean handleBuiltWhatTheyHad(String partName)
	{
		if (config.clearWhenBuilt())
		{
			materialsManager.remove(partName);
			if (panel != null)
			{
				panel.refresh();
			}
			return true;
		}

		return config.skipBuildable();
	}

	private boolean trackFromChatFallback(String partName, boolean moveToBottom)
	{
		Map<String, Integer> materials = chatMaterialsParser.getMaterials(partName);
		if (materials == null || materials.isEmpty())
		{
			return false;
		}

		materialsManager.track(partName, materials, guideLevelReader.findLevelRequirements(client, partName, "Construction"), moveToBottom);
		return true;
	}

	private WikiRecipeService.Recipe selectRecipe(List<WikiRecipeService.Recipe> recipes, String variant)
	{
		if (recipes.isEmpty())
		{
			return null;
		}
		if (variant != null)
		{
			for (WikiRecipeService.Recipe recipe : recipes)
			{
				if (variant.equalsIgnoreCase(recipe.getOutputSubtext()))
				{
					return recipe;
				}
			}
		}
		return recipes.get(0);
	}

	/**
	 * Only Sailing names use a trailing "(raft/skiff/sloop)" as a boat-size marker; a
	 * Construction parenthetical like "STASH units (beginner)" is part of the name itself.
	 */
	private String wikiVariant(String partName, String skill)
	{
		if (!"Sailing".equals(skill))
		{
			return null;
		}
		return PartNames.boatSizeOf(partName);
	}

	/**
	 * Ship facilities (Range, Keg, ...) share their name with unrelated pages and live under a
	 * "(facility)" suffix - "Range" is a cooking range, "Keg" is a disambiguation page. Boat
	 * parts resolve on the first candidate, so the second is only ever fetched on a miss.
	 */
	private List<String> wikiPageCandidates(String partName, String skill)
	{
		String pageName = wikiPageName(partName, skill);
		return "Sailing".equals(skill)
			? Arrays.asList(pageName, pageName + " (facility)")
			: Collections.singletonList(pageName);
	}

	private String wikiPageName(String partName, String skill)
	{
		if (!"Sailing".equals(skill))
		{
			return partName;
		}
		// The wiki files the raft variant under "<tier> hull" too.
		return PartNames.sharedName(partName);
	}

	/**
	 * One guide interface is shared by every skill, so being open isn't enough - its title says
	 * which skill it's showing. Read live, since the user can switch skills without reopening.
	 */
	private boolean isTrackedSkillGuideOpen()
	{
		refreshCachedGuideTitles();
		return matchingTrackedSkill(lastKnownGuideV2Title, true) != null
			|| matchingTrackedSkill(lastKnownGuideV1Title, false) != null;
	}

	private String matchingTrackedSkill(String title, boolean prefixMatch)
	{
		if (title == null)
		{
			return null;
		}
		for (String skill : TRACKED_SKILLS)
		{
			if (prefixMatch ? title.startsWith(skill) : skill.equals(title))
			{
				return skill;
			}
		}
		return null;
	}

	/**
	 * Whichever guide is open, else Sailing - the only other chat source is
	 * SAILING_CUSTOMISATION. Relies on {@link #isTrackedSkillGuideOpen()} having refreshed the
	 * cached titles earlier in the same event.
	 */
	private String currentSkillSource()
	{
		String skill = matchingTrackedSkill(lastKnownGuideV2Title, true);
		if (skill == null)
		{
			skill = matchingTrackedSkill(lastKnownGuideV1Title, false);
		}
		return skill != null ? skill : "Sailing";
	}

	private void refreshCachedGuideTitles()
	{
		// V2's FRAME is a static container whose own text is always empty - the title lives on a
		// dynamically-created child, so a direct getText() on it always comes back blank.
		String dynamicV2Text = findNonEmptyDynamicChildText(
			client.getWidget(InterfaceID.SKILL_GUIDE_V2, InterfaceID.SkillGuideV2.FRAME & 0xFFFF));
		if (dynamicV2Text != null)
		{
			lastKnownGuideV2Title = dynamicV2Text;
		}

		Widget titleV1 = client.getWidget(InterfaceID.SKILL_GUIDE, InterfaceID.SkillGuide.TITLE & 0xFFFF);
		if (titleV1 != null && titleV1.getText() != null && !titleV1.getText().isEmpty())
		{
			lastKnownGuideV1Title = titleV1.getText();
		}
	}

	private String findNonEmptyDynamicChildText(Widget parent)
	{
		if (parent == null)
		{
			return null;
		}
		Widget[] children = parent.getDynamicChildren();
		if (children == null)
		{
			return null;
		}
		for (Widget child : children)
		{
			if (child != null && child.getText() != null && !child.getText().isEmpty())
			{
				return child.getText();
			}
		}
		return null;
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (event.getGameState() == GameState.LOADING)
		{
			ticksSinceSceneLoad = 0;
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (ticksSinceSceneLoad < 0)
		{
			return;
		}

		// Built furniture is spawned a few ticks after the scene itself; scanning immediately
		// finds only the empty hotspots.
		if (++ticksSinceSceneLoad >= HOUSE_SCAN_DELAY_TICKS)
		{
			ticksSinceSceneLoad = -1;
			if (houseContents.scanScene() && panel != null)
			{
				panel.refresh();
			}
		}
	}

	@Subscribe
	public void onWidgetLoaded(WidgetLoaded event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankButtonManager.onBankWidgetLoaded();
		}
		else if (event.getGroupId() == InterfaceID.SAILING_CUSTOMISATION)
		{
			shipCustomisationOpen = true;
		}
		else if (event.getGroupId() == InterfaceID.POH_FURNITURE_CREATION)
		{
			furnitureCreationOpen = true;
		}
	}

	@Subscribe
	public void onWidgetClosed(WidgetClosed event)
	{
		if (event.getGroupId() == InterfaceID.BANKMAIN)
		{
			bankButtonManager.onBankWidgetClosed();
		}
		else if (event.getGroupId() == InterfaceID.SAILING_CUSTOMISATION)
		{
			shipCustomisationOpen = false;
		}
		else if (event.getGroupId() == InterfaceID.POH_FURNITURE_CREATION)
		{
			furnitureCreationOpen = false;
		}
		else if (event.getGroupId() == InterfaceID.SKILL_GUIDE_V2)
		{
			lastKnownGuideV2Title = null;
		}
		else if (event.getGroupId() == InterfaceID.SKILL_GUIDE)
		{
			lastKnownGuideV1Title = null;
		}
	}

	@Subscribe
	public void onItemContainerChanged(ItemContainerChanged event)
	{
		if (event.getContainerId() == InventoryID.BANK)
		{
			bankSnapshot.update(event.getItemContainer());
		}

		if (panel != null)
		{
			panel.refresh();
		}
	}

	@Subscribe
	public void onStatChanged(StatChanged event)
	{
		// Levels still read as 0 at the LOGGED_IN transition - they arrive in a later packet,
		// which this catches (along with any subsequent level-up).
		if (panel != null)
		{
			panel.refresh();
		}
	}

	@Subscribe
	public void onScriptPreFired(ScriptPreFired event)
	{
		bankGroupedView.onScriptPreFired(event.getScriptId());
	}

	@Subscribe
	public void onScriptPostFired(ScriptPostFired event)
	{
		bankGroupedView.onScriptPostFired(event.getScriptId());
		bankButtonManager.onScriptPostFired(event.getScriptId());
	}
}

package com.requiredmaterials;

import java.util.ArrayList;
import java.util.List;
import lombok.Data;

/**
 * Everything needed for one upgrade part, e.g. "Oak mast and linen sail" and its
 * list of required materials. Keyed by part name in {@link MaterialsManager} so
 * clicking the same requirement again just replaces this entry.
 */
@Data
public class TrackedRequirement
{
	private final String partName;
	private final List<RequiredMaterial> materials;

	/**
	 * Skill level requirements (e.g. "Level 6 Construction") - populated separately from
	 * materials, and may be empty if they weren't discoverable when this was tracked.
	 */
	private List<String> levelRequirements = new ArrayList<>();

	/**
	 * Things that must already be built rather than collected - furniture upgrades name the
	 * previous tier ("Tool store 3"). Shown as requirements, but not counted against the bank,
	 * and not checked when working out whether a build is possible: the client doesn't tell us
	 * what's in the player's house.
	 */
	private List<String> prerequisites = new ArrayList<>();

	/**
	 * Which skill this was tracked from (e.g. "Sailing", "Construction") - drives which
	 * side-panel accordion this shows up under.
	 */
	private String skill;
}

package com.requiredmaterials;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.function.Consumer;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Value;
import lombok.extern.slf4j.Slf4j;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Fetches materials and level requirements from a wiki page's "{{Recipe}}" templates. A page can
 * hold several - one per boat-size variant, named by "output1subtxt" - so callers pick from the
 * returned list. Cached per page for the plugin's lifetime.
 */
@Slf4j
@Singleton
public class WikiRecipeService
{
	private static final String API_URL = "https://oldschool.runescape.wiki/api.php?action=parse&prop=wikitext&format=json&redirects=true&page=";
	private static final String USER_AGENT = "RequiredMaterials-RuneLite-Plugin/1.0";
	// Disambiguation pages link either as plain wikilinks or through the plink/ilink templates.
	// Furniture pages carry the ids of the objects the build places in the house, versioned as
	// "id1"/"id2" when a page covers several variants.
	private static final Pattern OBJECT_ID_PATTERN = Pattern.compile("^\\|\\s*id\\d*\\s*=\\s*([0-9,\\s]+)$", Pattern.MULTILINE);
	private static final Pattern DISAMBIG_LINK_PATTERN =
		Pattern.compile("(?:\\[\\[|\\{\\{(?:plink|ilink)\\|)([^\\]|}]+)");

	@Inject
	private OkHttpClient okHttpClient;

	@Inject
	private Gson gson;

	private final Map<String, List<Recipe>> cache = new ConcurrentHashMap<>();

	@Value
	public static class Recipe
	{
		String outputSubtext;
		Map<String, Integer> materials;
		List<String> levelRequirements;
		/**
		 * Furniture that has to be standing already rather than collected - an upgrade's previous
		 * tier. Listed among the materials, but marked with a cost of zero and no quantity.
		 */
		Set<String> prerequisites;
	}

	/**
	 * Tries each candidate page in turn, stopping at the first with a recipe. Callback fires on
	 * OkHttp's thread, never the client thread - callers must hop back via ClientThread before
	 * touching any Client API.
	 */
	public void fetchRecipes(List<String> pageNames, Consumer<List<Recipe>> callback)
	{
		fetchCandidate(pageNames, 0, callback);
	}

	private void fetchCandidate(List<String> pageNames, int index, Consumer<List<Recipe>> callback)
	{
		if (index >= pageNames.size())
		{
			callback.accept(Collections.emptyList());
			return;
		}

		fetchRecipes(pageNames.get(index), recipes ->
		{
			if (!recipes.isEmpty() || index + 1 >= pageNames.size())
			{
				callback.accept(recipes);
				return;
			}
			fetchCandidate(pageNames, index + 1, callback);
		});
	}

	private void fetchRecipes(String pageName, Consumer<List<Recipe>> callback)
	{
		fetchRecipes(pageName, callback, true);
	}

	// followDisambiguation guards against chasing links indefinitely: only the first hop follows.
	private void fetchRecipes(String pageName, Consumer<List<Recipe>> callback, boolean followDisambiguation)
	{
		List<Recipe> cached = cache.get(pageName);
		if (cached != null)
		{
			callback.accept(cached);
			return;
		}

		fetchWikitext(pageName, wikitext ->
		{
			if (wikitext == null)
			{
				cache.put(pageName, Collections.emptyList());
				callback.accept(Collections.emptyList());
				return;
			}

			List<Recipe> recipes = parseRecipes(wikitext);
			if (recipes.isEmpty() && followDisambiguation)
			{
				String firstLink = firstDisambiguationLink(wikitext);
				if (firstLink != null)
				{
					fetchRecipes(firstLink, callback, false);
					return;
				}
			}

			cache.put(pageName, recipes);
			callback.accept(recipes);
		});
	}

	/**
	 * The object ids a piece of furniture puts in the house, so its presence can be checked
	 * against the scene. A page lists several when one build places several objects, or when the
	 * page covers more than one variant.
	 */
	void fetchObjectIds(String pageName, Consumer<Set<Integer>> callback)
	{
		fetchWikitext(pageName, wikitext ->
			callback.accept(wikitext == null ? Collections.emptySet() : parseObjectIds(wikitext)));
	}

	static Set<Integer> parseObjectIds(String wikitext)
	{
		Set<Integer> ids = new LinkedHashSet<>();
		Matcher matcher = OBJECT_ID_PATTERN.matcher(wikitext);
		while (matcher.find())
		{
			for (String id : matcher.group(1).split(","))
			{
				try
				{
					ids.add(Integer.parseInt(id.trim()));
				}
				catch (NumberFormatException ignored)
				{
					// These fields also carry things like "N/A".
				}
			}
		}
		return ids;
	}

	/** @param callback receives the page's wikitext, or null if it couldn't be fetched. */
	private void fetchWikitext(String pageName, Consumer<String> callback)
	{
		String url = API_URL + URLEncoder.encode(pageName.replace(' ', '_'), StandardCharsets.UTF_8);
		Request request = new Request.Builder().url(url).header("User-Agent", USER_AGENT).build();
		okHttpClient.newCall(request).enqueue(new Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				log.warn("Required materials: wiki lookup failed for '{}'", pageName, e);
				callback.accept(null);
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					callback.accept(!response.isSuccessful() || body == null ? null : extractWikitext(body.string()));
				}
				catch (Exception e)
				{
					log.warn("Required materials: failed to parse wiki response for '{}'", pageName, e);
					callback.accept(null);
				}
			}
		});
	}

	private String extractWikitext(String json)
	{
		JsonObject root = gson.fromJson(json, JsonObject.class);
		JsonObject parse = root.getAsJsonObject("parse");
		return parse == null ? null : parse.getAsJsonObject("wikitext").get("*").getAsString();
	}

	// Package-private so the wikitext parsing can be tested without any network access.
	List<Recipe> parseRecipes(String wikitext)
	{
		List<Recipe> recipes = new ArrayList<>();
		for (Map<String, String> params : extractTemplates(wikitext, "{{Recipe"))
		{
			recipes.add(buildRecipe(params));
		}
		return recipes;
	}

	/**
	 * A page with no recipe may be a disambiguation page (e.g. "Water pump" lists seven unrelated
	 * things). Its first link is the one we want.
	 */
	String firstDisambiguationLink(String wikitext)
	{
		if (!wikitext.contains("{{disambig"))
		{
			return null;
		}
		Matcher matcher = DISAMBIG_LINK_PATTERN.matcher(wikitext);
		return matcher.find() ? matcher.group(1).trim() : null;
	}

	private Recipe buildRecipe(Map<String, String> params)
	{
		Map<String, Integer> materials = new LinkedHashMap<>();
		Set<String> prerequisites = new LinkedHashSet<>();
		for (int i = 1; i <= 10; i++)
		{
			String name = params.get("mat" + i);
			if (name == null || name.isEmpty())
			{
				continue;
			}

			String quantity = params.get("mat" + i + "quantity");
			if (quantity == null || quantity.isEmpty())
			{
				// No quantity and an explicit cost of nothing marks the previous tier of an
				// upgrade. Both are needed: a real item can omit its quantity when one is meant
				// (Cat blanket's bolt of cloth), and it carries no cost field at all.
				if ("0".equals(params.get("mat" + i + "cost")))
				{
					prerequisites.add(name);
				}
				else
				{
					materials.put(name, 1);
				}
				continue;
			}

			try
			{
				materials.put(name, Integer.parseInt(quantity.trim()));
			}
			catch (NumberFormatException ignored)
			{
			}
		}

		List<String> levelRequirements = new ArrayList<>();
		addLevelRequirement(levelRequirements, params, "skill1", "skill1lvl");
		addLevelRequirement(levelRequirements, params, "skill2", "skill2lvl");

		return new Recipe(params.get("output1subtxt"), materials, levelRequirements, prerequisites);
	}

	private void addLevelRequirement(List<String> levelRequirements, Map<String, String> params, String skillKey, String levelKey)
	{
		String skill = params.get(skillKey);
		String level = params.get(levelKey);
		if (skill != null && !skill.isEmpty() && level != null && !level.isEmpty())
		{
			levelRequirements.add("Level " + level.trim() + " " + skill.trim());
		}
	}

	/**
	 * Finds every "{{marker ... }}" block by brace-depth matching, since templates nest.
	 */
	private List<Map<String, String>> extractTemplates(String wikitext, String marker)
	{
		List<Map<String, String>> templates = new ArrayList<>();
		int searchFrom = 0;
		while (true)
		{
			int start = wikitext.indexOf(marker, searchFrom);
			if (start == -1)
			{
				break;
			}

			int depth = 0;
			int i = start;
			int end = -1;
			while (i < wikitext.length() - 1)
			{
				if (wikitext.startsWith("{{", i))
				{
					depth++;
					i += 2;
				}
				else if (wikitext.startsWith("}}", i))
				{
					depth--;
					i += 2;
					if (depth == 0)
					{
						end = i;
						break;
					}
				}
				else
				{
					i++;
				}
			}

			if (end == -1)
			{
				break;
			}

			templates.add(parseTemplateParams(wikitext.substring(start + 2, end - 2)));
			searchFrom = end;
		}
		return templates;
	}

	private Map<String, String> parseTemplateParams(String block)
	{
		List<String> parts = splitRespectingNesting(block, '|');
		Map<String, String> params = new LinkedHashMap<>();
		for (int i = 1; i < parts.size(); i++)
		{
			int eq = parts.get(i).indexOf('=');
			if (eq == -1)
			{
				continue;
			}
			params.put(parts.get(i).substring(0, eq).trim(), parts.get(i).substring(eq + 1).trim());
		}
		return params;
	}

	private List<String> splitRespectingNesting(String s, char delimiter)
	{
		List<String> parts = new ArrayList<>();
		int depth = 0;
		StringBuilder current = new StringBuilder();
		for (int i = 0; i < s.length(); i++)
		{
			char c = s.charAt(i);
			if (c == '{' || c == '[')
			{
				depth++;
			}
			else if (c == '}' || c == ']')
			{
				depth--;
			}

			if (c == delimiter && depth == 0)
			{
				parts.add(current.toString());
				current.setLength(0);
			}
			else
			{
				current.append(c);
			}
		}
		parts.add(current.toString());
		return parts;
	}
}

package com.requiredmaterials;

import java.util.LinkedHashMap;
import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class BankSnapshotTest
{
	@Test
	public void roundTripsCounts()
	{
		Map<Integer, Integer> counts = new LinkedHashMap<>();
		counts.put(2353, 183);
		counts.put(973, 4);
		counts.put(590, 2);

		assertEquals(counts, BankSnapshot.decode(BankSnapshot.encode(counts)));
	}

	@Test
	public void handlesLargeQuantities()
	{
		Map<Integer, Integer> counts = new LinkedHashMap<>();
		counts.put(995, Integer.MAX_VALUE);

		assertEquals(counts, BankSnapshot.decode(BankSnapshot.encode(counts)));
	}

	@Test
	public void emptyAndMissingValuesDecodeToNothing()
	{
		assertTrue(BankSnapshot.decode(null).isEmpty());
		assertTrue(BankSnapshot.decode("").isEmpty());
		assertTrue(BankSnapshot.encode(new LinkedHashMap<>()).isEmpty());
	}

	@Test
	public void skipsMalformedEntriesRatherThanLosingTheRest()
	{
		// A truncated or hand-edited value shouldn't throw away the whole bank.
		Map<Integer, Integer> counts = BankSnapshot.decode("2353:183,rubbish,:5,7:,995:100");

		assertEquals(2, counts.size());
		assertEquals(Integer.valueOf(183), counts.get(2353));
		assertEquals(Integer.valueOf(100), counts.get(995));
	}
}

package com.requiredmaterials;

import java.util.Map;
import org.junit.Test;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class ChatMaterialsParserTest
{
	private final ChatMaterialsParser parser = new ChatMaterialsParser();

	@Test
	public void parsesNameThenQuantity()
	{
		assertFalse(parser.accumulate("Oak mast", "Oak logs x5, Iron nails x 20, Bolt of linen x5."));

		Map<String, Integer> materials = parser.getMaterials("Oak mast");
		assertEquals(3, materials.size());
		assertEquals(Integer.valueOf(5), materials.get("Oak logs"));
		assertEquals(Integer.valueOf(20), materials.get("Iron nails"));
		assertEquals(Integer.valueOf(5), materials.get("Bolt of linen"));
	}

	@Test
	public void parsesQuantityThenName()
	{
		assertFalse(parser.accumulate("Oak cargo hold", "8 x Oak plank, 32 x Iron nails."));

		Map<String, Integer> materials = parser.getMaterials("Oak cargo hold");
		assertEquals(Integer.valueOf(8), materials.get("Oak plank"));
		assertEquals(Integer.valueOf(32), materials.get("Iron nails"));
	}

	@Test
	public void stripsColourTags()
	{
		assertFalse(parser.accumulate("Part",
			"<col=ef1020>4 x Teak plank</col>, <col=ef1020>16 x Steel nails</col>."));

		Map<String, Integer> materials = parser.getMaterials("Part");
		assertEquals(Integer.valueOf(4), materials.get("Teak plank"));
		assertEquals(Integer.valueOf(16), materials.get("Steel nails"));
	}

	@Test
	public void treatsNonBreakingSpacesAsSpaces()
	{
		assertFalse(parser.accumulate("Part", "Oak logs\u00A0x\u00A05."));
		assertEquals(Integer.valueOf(5), parser.getMaterials("Part").get("Oak logs"));
	}

	@Test
	public void unclosedColourSpanExpectsAContinuation()
	{
		// The client cuts long lists mid-tag, leaving the last span open.
		assertTrue(parser.accumulate("Wind catcher",
			"<col=ef1020>8 x Steel bar</col>, <col=ef1020>10000 x Air"));
	}

	@Test
	public void continuationRestoresTheSpaceEatenByTheLineWrap()
	{
		// "...10000 x Air" + "rune, ..." must not glue into "Airrune".
		assertTrue(parser.accumulate("Wind catcher",
			"<col=ef1020>8 x Steel bar</col>, <col=ef1020>10000 x Air"));
		assertFalse(parser.appendContinuation("Wind catcher",
			"rune</col>, <col=ef1020>1 x Captured wind mote</col>"));

		Map<String, Integer> materials = parser.getMaterials("Wind catcher");
		assertEquals(Integer.valueOf(8), materials.get("Steel bar"));
		assertEquals(Integer.valueOf(10000), materials.get("Air rune"));
		assertEquals(Integer.valueOf(1), materials.get("Captured wind mote"));
	}

	@Test
	public void continuationJoiningDigitsDoesNotInsertASpace()
	{
		assertTrue(parser.accumulate("Part", "<col=ef1020>1"));
		assertFalse(parser.appendContinuation("Part", "0 x Oak plank</col>"));
		assertEquals(Integer.valueOf(10), parser.getMaterials("Part").get("Oak plank"));
	}

	@Test
	public void continuationForAnUnknownPartIsIgnored()
	{
		assertFalse(parser.appendContinuation("Never tracked", "rune</col>"));
	}

	@Test
	public void unparseableSegmentsAreSkippedRatherThanFailing()
	{
		assertFalse(parser.accumulate("Part", "Oak logs x5, some prose with no quantity."));

		Map<String, Integer> materials = parser.getMaterials("Part");
		assertEquals(1, materials.size());
		assertEquals(Integer.valueOf(5), materials.get("Oak logs"));
	}

	@Test
	public void untaggedMessagesAreCompleteOnTheirOwn()
	{
		// Items are only coloured when you're short of them, so affording everything can produce
		// a message with no tags and no trailing period. That isn't a truncated message.
		ChatMaterialsParser parser = new ChatMaterialsParser();

		assertFalse(parser.accumulate("Oak chest of drawers", "2 x Oak plank"));
		assertEquals(Integer.valueOf(2), parser.getMaterials("Oak chest of drawers").get("Oak plank"));
	}
}

